-- 0002: tenants, users, identities, memberships, teams, roles, securables, grants, sessions, audit.
--
-- Conventions (enforced by schema-lint):
--   * Tenant tables: tenant_id NOT NULL, PK (tenant_id, ...), composite FKs incl. tenant_id,
--     RLS ENABLE + FORCE, a RESTRICTIVE "<table>_tenant_isolation" policy for ios_app and ios_worker.
--   * Global tables (no tenant_id) are explicitly allow-listed in schema-lint with a reason,
--     and still have RLS ENABLE + FORCE.
--   * IDs are UUIDv7 generated by the application (no DB default: keeps PG16/17 compatible).

-- ===========================================================================
-- Helper functions used by policies. SECURITY INVOKER: they read RLS-protected
-- tables as the caller, inside the caller's tenant context.
-- IMPORTANT: they only read tables whose SELECT policies do NOT call them
-- (avoids policy recursion). schema-lint cannot prove this; tests do.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- tenants (global)
-- ---------------------------------------------------------------------------
CREATE TABLE tenants (
  id             uuid PRIMARY KEY,
  slug           text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
  name           text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
  status         text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'offboarding')),
  data_region    text NOT NULL DEFAULT 'eu-central-1',
  default_locale text NOT NULL DEFAULT 'en' CHECK (default_locale IN ('en', 'nl', 'de', 'fr')),
  created_at     timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- users (global identity; no tenant data)
-- ---------------------------------------------------------------------------
CREATE TABLE users (
  id           uuid PRIMARY KEY,
  email        text NOT NULL UNIQUE CHECK (email = lower(email) AND email LIKE '%_@_%'),
  display_name text NOT NULL CHECK (length(display_name) BETWEEN 1 AND 200),
  locale       text CHECK (locale IN ('en', 'nl', 'de', 'fr')),
  status       text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at   timestamptz NOT NULL DEFAULT now()
);

-- Login is bound to (issuer, subject) from the IdP. NEVER to e-mail.
CREATE TABLE user_identities (
  id         uuid PRIMARY KEY,
  user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  issuer     text NOT NULL CHECK (issuer ~ '^https?://'),
  subject    text NOT NULL CHECK (length(subject) BETWEEN 1 AND 255),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (issuer, subject)
);
CREATE INDEX user_identities_user_idx ON user_identities (user_id);

-- ---------------------------------------------------------------------------
-- tenant_memberships
-- ---------------------------------------------------------------------------
CREATE TABLE tenant_memberships (
  tenant_id       uuid NOT NULL REFERENCES tenants (id),
  id              uuid NOT NULL,
  user_id         uuid NOT NULL REFERENCES users (id),
  -- 'portal' is reserved for the future investor portal; blocked until that milestone.
  principal_type  text NOT NULL DEFAULT 'staff' CHECK (principal_type IN ('staff')),
  status          text NOT NULL DEFAULT 'active' CHECK (status IN ('invited', 'active', 'suspended')),
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, user_id)
);
CREATE INDEX tenant_memberships_user_idx ON tenant_memberships (user_id);

-- ---------------------------------------------------------------------------
-- teams
-- ---------------------------------------------------------------------------
CREATE TABLE teams (
  tenant_id  uuid NOT NULL REFERENCES tenants (id),
  id         uuid NOT NULL,
  name       text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, name)
);

CREATE TABLE team_members (
  tenant_id     uuid NOT NULL,
  team_id       uuid NOT NULL,
  membership_id uuid NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, team_id, membership_id),
  FOREIGN KEY (tenant_id, team_id) REFERENCES teams (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, membership_id) REFERENCES tenant_memberships (tenant_id, id) ON DELETE CASCADE
);
CREATE INDEX team_members_membership_idx ON team_members (tenant_id, membership_id);

-- ---------------------------------------------------------------------------
-- roles
-- ---------------------------------------------------------------------------
CREATE TABLE roles (
  tenant_id  uuid NOT NULL REFERENCES tenants (id),
  id         uuid NOT NULL,
  key        text NOT NULL CHECK (key ~ '^[a-z][a-z0-9_]{1,62}$'),
  name       text NOT NULL,
  is_system  boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, key)
);

CREATE TABLE role_permissions (
  tenant_id  uuid NOT NULL,
  role_id    uuid NOT NULL,
  permission text NOT NULL REFERENCES meta.permissions (key),
  PRIMARY KEY (tenant_id, role_id, permission),
  FOREIGN KEY (tenant_id, role_id) REFERENCES roles (tenant_id, id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------------
-- securables: every resource that can be classified 'restricted' (projects,
-- funds, opportunities, offerings, ...) registers exactly one securable row.
-- Child records (tasks, interactions, documents, subscriptions, ledger lines,
-- audit events, embeddings) carry securable_id and inherit its visibility
-- through RLS. Classification changes take effect immediately for all children.
-- ---------------------------------------------------------------------------
CREATE TABLE securables (
  tenant_id      uuid NOT NULL REFERENCES tenants (id),
  id             uuid NOT NULL,
  kind           text NOT NULL CHECK (kind ~ '^[a-z][a-z_]{1,40}$'),
  classification text NOT NULL DEFAULT 'standard' CHECK (classification IN ('standard', 'restricted')),
  created_at     timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id)
);

CREATE TABLE securable_grants (
  tenant_id     uuid NOT NULL,
  id            uuid NOT NULL,
  securable_id  uuid NOT NULL,
  membership_id uuid,
  team_id       uuid,
  access        text NOT NULL CHECK (access IN ('read', 'write')),
  expires_at    timestamptz,
  granted_by    uuid NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  CHECK ((membership_id IS NULL) <> (team_id IS NULL)),
  FOREIGN KEY (tenant_id, securable_id) REFERENCES securables (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, membership_id) REFERENCES tenant_memberships (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, team_id) REFERENCES teams (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, granted_by) REFERENCES tenant_memberships (tenant_id, id)
);
CREATE INDEX securable_grants_membership_idx ON securable_grants (tenant_id, membership_id) WHERE membership_id IS NOT NULL;
CREATE INDEX securable_grants_team_idx ON securable_grants (tenant_id, team_id) WHERE team_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- role_assignments: tenant-wide or scoped to one securable.
-- ---------------------------------------------------------------------------
CREATE TABLE role_assignments (
  tenant_id     uuid NOT NULL,
  id            uuid NOT NULL,
  role_id       uuid NOT NULL,
  membership_id uuid,
  team_id       uuid,
  scope_type    text NOT NULL DEFAULT 'tenant' CHECK (scope_type IN ('tenant', 'securable')),
  scope_id      uuid,
  granted_by    uuid,
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  CHECK ((membership_id IS NULL) <> (team_id IS NULL)),
  CHECK ((scope_type = 'tenant') = (scope_id IS NULL)),
  FOREIGN KEY (tenant_id, role_id) REFERENCES roles (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, membership_id) REFERENCES tenant_memberships (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, team_id) REFERENCES teams (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, scope_id) REFERENCES securables (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, granted_by) REFERENCES tenant_memberships (tenant_id, id)
);
CREATE INDEX role_assignments_membership_idx ON role_assignments (tenant_id, membership_id) WHERE membership_id IS NOT NULL;
CREATE INDEX role_assignments_team_idx ON role_assignments (tenant_id, team_id) WHERE team_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- sessions (global; server-side; the browser only holds an opaque random token,
-- the DB only holds its SHA-256)
-- ---------------------------------------------------------------------------
CREATE TABLE sessions (
  id                   uuid PRIMARY KEY,
  token_hash           bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
  user_id              uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  active_tenant_id     uuid,
  active_membership_id uuid,
  created_at           timestamptz NOT NULL DEFAULT now(),
  last_seen_at         timestamptz NOT NULL DEFAULT now(),
  expires_at           timestamptz NOT NULL,
  revoked_at           timestamptz,
  CHECK ((active_tenant_id IS NULL) = (active_membership_id IS NULL)),
  FOREIGN KEY (active_tenant_id, active_membership_id) REFERENCES tenant_memberships (tenant_id, id) ON DELETE SET NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

-- ---------------------------------------------------------------------------
-- audit_events: append-only. Hash chain + WORM export arrive in M2; the
-- prev_hash/hash columns exist now so the format does not change later.
-- ---------------------------------------------------------------------------
CREATE TABLE audit_events (
  tenant_id           uuid NOT NULL REFERENCES tenants (id),
  id                  uuid NOT NULL,
  seq                 bigint GENERATED ALWAYS AS IDENTITY,
  occurred_at         timestamptz NOT NULL DEFAULT now(),
  actor_type          text NOT NULL CHECK (actor_type IN ('user', 'system')),
  actor_membership_id uuid,
  actor_label         text,
  action              text NOT NULL CHECK (action ~ '^[a-z]+(\.[a-z_]+)+$'),
  target_type         text,
  target_id           uuid,
  securable_id        uuid,
  request_id          text,
  changes             jsonb NOT NULL DEFAULT '{}'::jsonb,
  prev_hash           bytea,
  hash                bytea,
  PRIMARY KEY (tenant_id, id),
  CHECK ((actor_type = 'user') = (actor_membership_id IS NOT NULL)),
  FOREIGN KEY (tenant_id, actor_membership_id) REFERENCES tenant_memberships (tenant_id, id),
  FOREIGN KEY (tenant_id, securable_id) REFERENCES securables (tenant_id, id)
);
CREATE INDEX audit_events_tenant_seq_idx ON audit_events (tenant_id, seq);

CREATE FUNCTION app.audit_events_immutable() RETURNS trigger
  LANGUAGE plpgsql AS
$$
BEGIN
  RAISE EXCEPTION 'audit_events is append-only (% blocked)', TG_OP USING ERRCODE = 'insufficient_privilege';
END
$$;
CREATE TRIGGER audit_events_no_update BEFORE UPDATE OR DELETE ON audit_events
  FOR EACH ROW EXECUTE FUNCTION app.audit_events_immutable();
CREATE TRIGGER audit_events_no_truncate BEFORE TRUNCATE ON audit_events
  FOR EACH STATEMENT EXECUTE FUNCTION app.audit_events_immutable();

-- ===========================================================================
-- Authorization helper functions (SECURITY INVOKER, STABLE).
-- Policies call them wrapped in a scalar sub-select, e.g. (SELECT app.has_permission('x')),
-- so the planner evaluates them once per statement (InitPlan), not per row.
-- ===========================================================================

-- Is the current membership active in the current tenant?
CREATE FUNCTION app.membership_active() RETURNS boolean
  LANGUAGE sql STABLE AS
$$
  SELECT EXISTS (
    SELECT 1 FROM tenant_memberships m
    WHERE m.tenant_id = app.current_tenant()
      AND m.id = app.current_membership()
      AND m.user_id = app.current_user_id()
      AND m.status = 'active'
  )
$$;

CREATE FUNCTION app.my_team_ids() RETURNS uuid[]
  LANGUAGE sql STABLE AS
$$
  SELECT coalesce(array_agg(tm.team_id), '{}')
  FROM team_members tm
  WHERE tm.tenant_id = app.current_tenant() AND tm.membership_id = app.current_membership()
$$;

-- Tenant-wide permission check (scoped assignments are evaluated per resource in the app layer).
CREATE FUNCTION app.has_permission(p_permission text) RETURNS boolean
  LANGUAGE sql STABLE AS
$$
  SELECT app.membership_active() AND EXISTS (
    SELECT 1
    FROM role_assignments ra
    JOIN role_permissions rp ON rp.tenant_id = ra.tenant_id AND rp.role_id = ra.role_id
    WHERE ra.tenant_id = app.current_tenant()
      AND ra.scope_type = 'tenant'
      AND (ra.membership_id = app.current_membership() OR ra.team_id = ANY (app.my_team_ids()))
      AND rp.permission = p_permission
  )
$$;

-- Restricted securables the current membership holds a live grant on (direct or via team).
-- p_access = 'read' accepts read or write grants; 'write' only write grants.
CREATE FUNCTION app.granted_securables(p_access text) RETURNS uuid[]
  LANGUAGE sql STABLE AS
$$
  SELECT coalesce(array_agg(DISTINCT g.securable_id), '{}')
  FROM securable_grants g
  WHERE app.membership_active()
    AND g.tenant_id = app.current_tenant()
    AND (g.membership_id = app.current_membership() OR g.team_id = ANY (app.my_team_ids()))
    AND (g.expires_at IS NULL OR g.expires_at > now())
    AND (p_access = 'read' OR g.access = 'write')
$$;

-- Child-table helpers. They read `securables` under its own RLS, so a securable the caller
-- cannot see behaves exactly like a securable that does not exist (default deny).
CREATE FUNCTION app.securable_visible(p_tenant uuid, p_securable uuid) RETURNS boolean
  LANGUAGE sql STABLE AS
$$
  SELECT EXISTS (SELECT 1 FROM securables s WHERE s.tenant_id = p_tenant AND s.id = p_securable)
$$;

CREATE FUNCTION app.securable_writable(p_tenant uuid, p_securable uuid) RETURNS boolean
  LANGUAGE sql STABLE AS
$$
  SELECT EXISTS (
    SELECT 1 FROM securables s
    WHERE s.tenant_id = p_tenant AND s.id = p_securable
      AND (s.classification = 'standard' OR s.id = ANY (app.granted_securables('write')))
  )
$$;

GRANT EXECUTE ON FUNCTION app.membership_active(), app.my_team_ids(), app.has_permission(text),
  app.granted_securables(text), app.securable_visible(uuid, uuid), app.securable_writable(uuid, uuid)
  TO ios_app, ios_worker;

-- ===========================================================================
-- Row-Level Security
-- ===========================================================================
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;            ALTER TABLE tenants FORCE ROW LEVEL SECURITY;
ALTER TABLE users ENABLE ROW LEVEL SECURITY;              ALTER TABLE users FORCE ROW LEVEL SECURITY;
ALTER TABLE user_identities ENABLE ROW LEVEL SECURITY;    ALTER TABLE user_identities FORCE ROW LEVEL SECURITY;
ALTER TABLE tenant_memberships ENABLE ROW LEVEL SECURITY; ALTER TABLE tenant_memberships FORCE ROW LEVEL SECURITY;
ALTER TABLE teams ENABLE ROW LEVEL SECURITY;              ALTER TABLE teams FORCE ROW LEVEL SECURITY;
ALTER TABLE team_members ENABLE ROW LEVEL SECURITY;       ALTER TABLE team_members FORCE ROW LEVEL SECURITY;
ALTER TABLE roles ENABLE ROW LEVEL SECURITY;              ALTER TABLE roles FORCE ROW LEVEL SECURITY;
ALTER TABLE role_permissions ENABLE ROW LEVEL SECURITY;   ALTER TABLE role_permissions FORCE ROW LEVEL SECURITY;
ALTER TABLE securables ENABLE ROW LEVEL SECURITY;         ALTER TABLE securables FORCE ROW LEVEL SECURITY;
ALTER TABLE securable_grants ENABLE ROW LEVEL SECURITY;   ALTER TABLE securable_grants FORCE ROW LEVEL SECURITY;
ALTER TABLE role_assignments ENABLE ROW LEVEL SECURITY;   ALTER TABLE role_assignments FORCE ROW LEVEL SECURITY;
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;           ALTER TABLE sessions FORCE ROW LEVEL SECURITY;
ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;       ALTER TABLE audit_events FORCE ROW LEVEL SECURITY;

-- --- tenants: a user sees the tenants they hold an active membership in. Read-only for the app;
-- provisioning goes through a dedicated provisioning path (M1), never a user request.
CREATE POLICY tenants_member_read ON tenants FOR SELECT TO ios_app, ios_worker
  USING (
    id = app.current_tenant()
    OR id IN (SELECT m.tenant_id FROM tenant_memberships m
              WHERE m.user_id = app.current_user_id() AND m.status = 'active')
  );

-- --- users: yourself, plus colleagues in the current tenant.
CREATE POLICY users_read ON users FOR SELECT TO ios_app, ios_worker
  USING (
    id = app.current_user_id()
    OR id IN (SELECT m.user_id FROM tenant_memberships m WHERE m.tenant_id = app.current_tenant())
  );
CREATE POLICY users_update_self ON users FOR UPDATE TO ios_app
  USING (id = app.current_user_id()) WITH CHECK (id = app.current_user_id());
CREATE POLICY users_definer_read ON users FOR SELECT TO ios_definer USING (true);

-- --- user_identities: your own only. Pre-login resolution uses auth.resolve_identity().
CREATE POLICY user_identities_self ON user_identities FOR SELECT TO ios_app, ios_worker
  USING (user_id = app.current_user_id());
CREATE POLICY user_identities_definer_read ON user_identities FOR SELECT TO ios_definer USING (true);

-- --- tenant_memberships: restrictive tenant isolation, with one deliberate widening:
-- a user can read their OWN memberships across tenants (for the tenant switcher).
CREATE POLICY tenant_memberships_tenant_isolation ON tenant_memberships AS RESTRICTIVE FOR ALL TO ios_app, ios_worker
  USING (tenant_id = app.current_tenant() OR user_id = app.current_user_id())
  WITH CHECK (tenant_id = app.current_tenant());
CREATE POLICY tenant_memberships_read ON tenant_memberships FOR SELECT TO ios_app, ios_worker USING (true);
CREATE POLICY tenant_memberships_insert ON tenant_memberships FOR INSERT TO ios_app
  WITH CHECK ((SELECT app.has_permission('iam.members.manage')));
CREATE POLICY tenant_memberships_update ON tenant_memberships FOR UPDATE TO ios_app
  USING ((SELECT app.has_permission('iam.members.manage')))
  WITH CHECK ((SELECT app.has_permission('iam.members.manage')));
CREATE POLICY tenant_memberships_delete ON tenant_memberships FOR DELETE TO ios_app
  USING ((SELECT app.has_permission('iam.members.manage')));

-- --- Generic tenant tables. SELECT policies are tenant-only (helper functions read these
-- tables; a permission check here would recurse). Writes require a permission.
CREATE POLICY teams_tenant_isolation ON teams AS RESTRICTIVE FOR ALL TO ios_app, ios_worker
  USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
CREATE POLICY teams_read ON teams FOR SELECT TO ios_app, ios_worker USING (true);
CREATE POLICY teams_write ON teams FOR ALL TO ios_app
  USING ((SELECT app.has_permission('iam.teams.manage'))) WITH CHECK ((SELECT app.has_permission('iam.teams.manage')));

CREATE POLICY team_members_tenant_isolation ON team_members AS RESTRICTIVE FOR ALL TO ios_app, ios_worker
  USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
CREATE POLICY team_members_read ON team_members FOR SELECT TO ios_app, ios_worker USING (true);
CREATE POLICY team_members_write ON team_members FOR ALL TO ios_app
  USING ((SELECT app.has_permission('iam.teams.manage'))) WITH CHECK ((SELECT app.has_permission('iam.teams.manage')));

CREATE POLICY roles_tenant_isolation ON roles AS RESTRICTIVE FOR ALL TO ios_app, ios_worker
  USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
CREATE POLICY roles_read ON roles FOR SELECT TO ios_app, ios_worker USING (true);
CREATE POLICY roles_write ON roles FOR ALL TO ios_app
  USING ((SELECT app.has_permission('iam.roles.manage')) AND NOT is_system)
  WITH CHECK ((SELECT app.has_permission('iam.roles.manage')) AND NOT is_system);

CREATE POLICY role_permissions_tenant_isolation ON role_permissions AS RESTRICTIVE FOR ALL TO ios_app, ios_worker
  USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
CREATE POLICY role_permissions_read ON role_permissions FOR SELECT TO ios_app, ios_worker USING (true);
CREATE POLICY role_permissions_write ON role_permissions FOR ALL TO ios_app
  USING ((SELECT app.has_permission('iam.roles.manage'))
         AND NOT EXISTS (SELECT 1 FROM roles r WHERE r.tenant_id = role_permissions.tenant_id AND r.id = role_permissions.role_id AND r.is_system))
  WITH CHECK ((SELECT app.has_permission('iam.roles.manage'))
         AND NOT EXISTS (SELECT 1 FROM roles r WHERE r.tenant_id = role_permissions.tenant_id AND r.id = role_permissions.role_id AND r.is_system));

CREATE POLICY role_assignments_tenant_isolation ON role_assignments AS RESTRICTIVE FOR ALL TO ios_app, ios_worker
  USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
CREATE POLICY role_assignments_read ON role_assignments FOR SELECT TO ios_app, ios_worker USING (true);
CREATE POLICY role_assignments_write ON role_assignments FOR ALL TO ios_app
  USING ((SELECT app.has_permission('iam.roles.manage'))) WITH CHECK ((SELECT app.has_permission('iam.roles.manage')));

-- --- securables: restricted rows are invisible without a live grant (or compliance oversight).
-- This is the database-enforced information barrier.
CREATE POLICY securables_tenant_isolation ON securables AS RESTRICTIVE FOR ALL TO ios_app, ios_worker
  USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
CREATE POLICY securables_read ON securables FOR SELECT TO ios_app, ios_worker
  USING (
    classification = 'standard'
    OR id = ANY ((SELECT app.granted_securables('read'))::uuid[])
    OR (SELECT app.has_permission('restricted.oversight'))
  );
CREATE POLICY securables_insert ON securables FOR INSERT TO ios_app
  WITH CHECK ((SELECT app.has_permission('securables.manage')));
-- Changing a restricted securable (incl. de-classifying it) requires a write grant on it.
CREATE POLICY securables_update ON securables FOR UPDATE TO ios_app
  USING ((SELECT app.has_permission('securables.manage'))
         AND (classification = 'standard' OR id = ANY ((SELECT app.granted_securables('write'))::uuid[])))
  WITH CHECK ((SELECT app.has_permission('securables.manage')));
CREATE POLICY securables_delete ON securables FOR DELETE TO ios_app
  USING ((SELECT app.has_permission('securables.manage'))
         AND (classification = 'standard' OR id = ANY ((SELECT app.granted_securables('write'))::uuid[])));

-- --- securable_grants: visible to the grantee (direct or via team) and to access managers.
CREATE POLICY securable_grants_tenant_isolation ON securable_grants AS RESTRICTIVE FOR ALL TO ios_app, ios_worker
  USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
CREATE POLICY securable_grants_read ON securable_grants FOR SELECT TO ios_app, ios_worker
  USING (
    membership_id = app.current_membership()
    OR team_id = ANY ((SELECT app.my_team_ids())::uuid[])
    OR (SELECT app.has_permission('access.manage'))
  );
CREATE POLICY securable_grants_write ON securable_grants FOR ALL TO ios_app
  USING ((SELECT app.has_permission('access.manage')))
  WITH CHECK ((SELECT app.has_permission('access.manage')) AND granted_by = app.current_membership());

-- --- sessions: your own sessions only. Pre-context lookup uses auth.lookup_session().
CREATE POLICY sessions_self ON sessions FOR ALL TO ios_app
  USING (user_id = app.current_user_id())
  WITH CHECK (
    user_id = app.current_user_id()
    AND (revoked_at IS NOT NULL OR active_membership_id IS NULL OR EXISTS (
      SELECT 1 FROM tenant_memberships m
      WHERE m.tenant_id = sessions.active_tenant_id AND m.id = sessions.active_membership_id
        AND m.user_id = sessions.user_id AND m.status = 'active'))
  );
CREATE POLICY sessions_definer_read ON sessions FOR SELECT TO ios_definer USING (true);
CREATE POLICY sessions_definer_touch ON sessions FOR UPDATE TO ios_definer USING (true) WITH CHECK (true);

-- --- audit_events: append-only; reading requires audit.read AND visibility of the securable.
CREATE POLICY audit_events_tenant_isolation ON audit_events AS RESTRICTIVE FOR ALL TO ios_app, ios_worker
  USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
CREATE POLICY audit_events_read ON audit_events FOR SELECT TO ios_app, ios_worker
  USING ((SELECT app.has_permission('audit.read'))
         AND (securable_id IS NULL OR app.securable_visible(tenant_id, securable_id)));
CREATE POLICY audit_events_insert_user ON audit_events FOR INSERT TO ios_app, ios_worker
  WITH CHECK (
    (actor_type = 'user' AND actor_membership_id = app.current_membership() AND (SELECT app.membership_active()))
    OR (actor_type = 'system' AND app.principal_type() = 'system')
  );

-- ===========================================================================
-- Grants (least privilege). Nothing is granted on tables not listed here.
-- ===========================================================================
GRANT SELECT ON tenants TO ios_app, ios_worker;
GRANT SELECT, UPDATE (display_name, locale) ON users TO ios_app;
GRANT SELECT ON users TO ios_worker, ios_definer;
GRANT SELECT ON user_identities TO ios_app, ios_worker, ios_definer;
GRANT SELECT, INSERT, UPDATE, DELETE ON tenant_memberships, teams, team_members, roles, role_permissions,
  role_assignments, securables, securable_grants TO ios_app;
GRANT SELECT ON tenant_memberships, teams, team_members, roles, role_permissions, role_assignments,
  securables, securable_grants TO ios_worker;
GRANT SELECT, INSERT, UPDATE ON sessions TO ios_app;
GRANT SELECT, UPDATE (last_seen_at) ON sessions TO ios_definer;
GRANT SELECT, INSERT ON audit_events TO ios_app, ios_worker;

-- ===========================================================================
-- Pre-context auth functions (SECURITY DEFINER, owned by ios_definer, which
-- has NO BYPASSRLS: it only reaches rows through the *_definer_* policies above).
-- search_path pinned to prevent object-shadowing attacks.
-- ===========================================================================
CREATE FUNCTION auth.resolve_identity(p_issuer text, p_subject text) RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS
$$
  SELECT u.id
  FROM public.user_identities ui
  JOIN public.users u ON u.id = ui.user_id
  WHERE ui.issuer = p_issuer AND ui.subject = p_subject AND u.status = 'active'
$$;

-- Returns the live session for a token hash and slides its idle window. No row = no session.
CREATE FUNCTION auth.lookup_session(p_token_hash bytea, p_idle_seconds integer)
  RETURNS TABLE (session_id uuid, user_id uuid, active_tenant_id uuid, active_membership_id uuid, expires_at timestamptz)
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS
$$
BEGIN
  RETURN QUERY
  UPDATE public.sessions s SET last_seen_at = now()
  FROM public.users u
  WHERE s.token_hash = p_token_hash
    AND u.id = s.user_id AND u.status = 'active'
    AND s.revoked_at IS NULL
    AND s.expires_at > now()
    AND s.last_seen_at > now() - make_interval(secs => p_idle_seconds)
  RETURNING s.id, s.user_id, s.active_tenant_id, s.active_membership_id, s.expires_at;
END
$$;

-- Ownership transfer needs the migrator's own membership in ios_definer (ios_owner is not a member).
RESET ROLE;
ALTER FUNCTION auth.resolve_identity(text, text) OWNER TO ios_definer;
ALTER FUNCTION auth.lookup_session(bytea, integer) OWNER TO ios_definer;
REVOKE ALL ON FUNCTION auth.resolve_identity(text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION auth.lookup_session(bytea, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION auth.resolve_identity(text, text) TO ios_app;
GRANT EXECUTE ON FUNCTION auth.lookup_session(bytea, integer) TO ios_app;
SET ROLE ios_owner;
